type Task = { title: string; done: boolean };

function countWhere(tasks: readonly Task[], test: (task: Task) => boolean): number {
  let count = 0;
  for (const task of tasks) {
    if (test(task)) count += 1;
  }
  return count;
}

const tasks: Task[] = [
  { title: "Buy milk", done: true },
  { title: "Call Ada", done: false },
  { title: "File taxes", done: true },
];

